// Executes original source algorithms only. Authored boundary callbacks are
// synchronous/deferred fixtures; provider durability/native recovery is separate.
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using FSO.SimAntics;using FSO.SimAntics.NetPlay.EODs;using FSO.SimAntics.NetPlay.EODs.Handlers;using FSO.SimAntics.NetPlay.EODs.Handlers.Data;using FSO.SimAntics.NetPlay.Model;using FSO.SimAntics.NetPlay.Model.Commands;
class SourceOracle {
 static string Hex(byte[] b){return BitConverter.ToString(b).Replace("-","").ToLowerInvariant();}
 static byte[] Save(VMSerializable data){using(var m=new MemoryStream()){var w=new BinaryWriter(m);data.SerializeInto(w);return m.ToArray();}}
 static string Events(VMEODClient c){return String.Join(";",c.Events.Select(e=>e.Code+":"+String.Join(",",e.Data)));}
 static void Row(string key,object value){Console.WriteLine(key+"="+value);}
 static VMEODClient Client(VMEODServer s,uint id=1,short param=0){var c=new VMEODClient{vm=s.vm,Avatar=new VMAvatar{ObjectID=(short)id,PersistID=id},Invoker=new VMEntity{ObjectID=(short)(1000+id)}};c.Invoker.Thread.TempRegisters[0]=param;s.Clients.Add(c);return c;}
 static void Property(){var s=new VMEODServer(new VM(),0x2000);var h=new VMEODPropertySelectPlugin(s);s.Handler=h;var c=Client(s,1,-32768);c.Invoker.Thread.TempRegisters[1]=1;h.OnConnection(c);h.Tick();Row("property.show",c.Ui.Last().Split(':')[2]);h.B_Select("property_select",new byte[]{0x78,0x56,0x34,0x12,65,195,169},c);Row("property.events",Events(c));}
 static void Bulletin(){var s=new VMEODServer(new VM(),0x1003);var h=new VMEODBulletinPlugin(s);s.Handler=h;var c=Client(s,1,2);h.OnConnection(c);h.P_Mode("bulletin_mode","0",c);h.P_Mode("bulletin_mode","1",c);h.P_Mode("bulletin_mode","2",c);Row("bulletin.first",Events(c));h.S_AnimChanged(1,c);h.S_AnimChanged(1,c);h.P_Mode("bulletin_mode","1",c);Row("bulletin.latest",Events(c));c.Events.Clear();h.P_Posted("bulletin_posted","",c);h.P_Posted("bulletin_posted","",c);Row("bulletin.posted",s.vm.GlobalLink.BulletinQueries+"/"+Events(c));}
 static void Newspaper(){var d=new VMEODFNewspaperData();d.News.Add(new VMEODFNewspaperNews{ID=9,Name="A headline",Description="A private local newspaper description",StartDate=100,EndDate=200});d.Points.Add(new VMEODFNewspaperPoint{Day=123,Skilltype=4,Multiplier=1.25f,Flags=2});Row("newspaper.bytes",Hex(Save(d)));}
 static void Draw(){var s=new VMEODServer(new VM(),0x895C1CEB);s.vm.GlobalLink.Data=new VMEODGameCompDrawACardData{GameTitle="Lucky",GameDescription="Two cards",LastIndex=0,CardText=new List<string>{"First","Second"},EachCardsCount=new List<byte>{1,99}}.Save();s.vm.GlobalLink.Deferred=true;var h=new VMEODGameCompDrawACardPlugin(s);s.Handler=h;var c=Client(s);h.OnConnection(c);Row("draw.wait",c.Ui.Last());s.vm.GlobalLink.Release();h.BinaryHandlers["DrawCard_Add_Card"]("",VMEODGameCompDrawACardData.SerializeStrings("Third","255"),c);Row("draw.count",c.Ui.First(x=>x.StartsWith("DrawCard_Update_Deck_Numbers")&&x.EndsWith("03333535")));h.BinaryHandlers["DrawCard_Goto_Card"]("",new byte[]{1},c);h.BinaryHandlers["DrawCard_Edit_Frequency"]("",new byte[]{0},c);h.BinaryHandlers["DrawCard_Edit_Frequency"]("",new byte[]{2},c);h.BinaryHandlers["DrawCard_Edit_Card"]("",VMEODGameCompDrawACardData.SerializeStrings("Updated"),c);h.BinaryHandlers["DrawCard_Edit_Game"]("",VMEODGameCompDrawACardData.SerializeStrings("New title","New rules"),c);h.OnDisconnection(c);Row("draw.save",Hex(s.vm.GlobalLink.Writes.Single()));Row("draw.saved_event",Events(c));try{h.BinaryHandlers["DrawCard_Add_Card"]("",VMEODGameCompDrawACardData.SerializeStrings(new string('a',39)+"😀Z","1"),c);Row("draw.source_utf16","accepted");}catch(Exception ex){Row("draw.source_utf16",ex.GetType().Name);}var empty=new VMEODGameCompDrawACardData{GameTitle="T",GameDescription="D",CardText=new List<string>(),EachCardsCount=new List<byte>()};try{new CarducopiaDrawACardGame(empty);Row("draw.source_empty","accepted");}catch(Exception ex){Row("draw.source_empty",ex.GetType().Name);}}
 static void Cooldown(){foreach(bool community in new[]{false,true})for(short mode=0;mode<8;mode++){var vm=new VM();vm.TSOState.CommunityLot=community;vm.GlobalLink.CooldownAllowed=mode%2==0;var s=new VMEODServer(vm,0x1004);var h=new VMEODCooldownEventPlugin(s);s.Handler=h;var c=Client(s,1,mode);c.Invoker.Thread.TempRegisters[1]=1;c.Invoker.Thread.TempRegisters[2]=2;c.Invoker.Thread.TempRegisters[3]=3;bool local=mode<=1||(community&&(mode==5||mode==7));if(local&&mode%2==1){var d=new VMEODCooldownEventPluginCommunityData();d.AvatarIDUserIDTimeStamps.Add(Tuple.Create(1u,10u,vm.GlobalLink.Expires.Ticks));vm.GlobalLink.Data=d.Save();}h.OnConnection(c);Row("cooldown."+(community?1:0)+"."+mode,Events(c));}var data=new VMEODCooldownEventPluginCommunityData();data.AvatarIDUserIDTimeStamps.Add(Tuple.Create(1u,10u,500L));data.AvatarIDUserIDTimeStamps.Add(Tuple.Create(2u,20u,300L));Row("cooldown.tuples",Hex(data.Save()));}
 static void Trunk(){foreach(short kind in new short[]{0,5}){var s=new VMEODServer(new VM(),0xAA5E36DC);var h=new VMEODTrunkPlugin(s);s.Handler=h;var c=Client(s,1,kind);c.Avatar.Gender=(short)(kind==5?1:0);h.OnConnection(c);Row("trunk."+kind+".show",c.Ui.Last());h.PlaintextHandlers["trunk_wear_costume"]("",kind==5?"not an asset":"123",c);var cmd=(VMNetSetOutfitCmd)s.vm.Commands.Single();Row("trunk."+kind+".command",cmd.UID+","+(int)cmd.Scope+","+cmd.Outfit);Row("trunk."+kind+".event",Events(c));}}
 static void Trade(){var s=new VMEODServer(new VM(),0x897F82F5);var h=new VMEODSecureTradePlugin(s);s.Handler=h;var a=Client(s,1);var b=Client(s,2);h.OnConnection(a);h.OnConnection(b);h.TradeOffer("","i101|0",a);Row("trade.offer",a.Ui.Last(x=>x.StartsWith("trade_me:b:")).Split(':')[2]);h.TradeOffer("","a",a);h.TradeOffer("","a",b);Row("trade.before_delay",s.vm.GlobalLink.Trades);for(int i=0;i<150;i++)h.Tick();h.TradeOffer("","a",a);h.TradeOffer("","a",b);Row("trade.after_delay",s.vm.GlobalLink.Trades);var s2=new VMEODServer(new VM(),0x897F82F5);var h2=new VMEODSecureTradePlugin(s2);s2.Handler=h2;var a2=Client(s2,1);var b2=Client(s2,2);h2.OnConnection(a2);h2.OnConnection(b2);h2.TradeOffer("","m50",a2);a2.Ui.Clear();h2.TradeOffer("","m0",a2);Row("trade.source_zero_update",a2.Ui.Count);h2.TradeOffer("","po0",a2);h2.TradeOffer("","po1",a2);var offer=a2.Ui.Last(x=>x.StartsWith("trade_me:b:")).Split(':')[2];var d=new VMEODSecureTradePlayer();d.Deserialize(new BinaryReader(new MemoryStream(Enumerable.Range(0,offer.Length/2).Select(i=>Convert.ToByte(offer.Substring(i*2,2),16)).ToArray())));Row("trade.source_duplicate_properties",d.ObjectOffer.Count(o=>o!=null&&o.LotID!=0));}
 static void Main(){Property();Bulletin();Newspaper();Draw();Cooldown();Trunk();Trade();}
}
